-- 1. Crear esquema
CREATE SCHEMA IF NOT EXISTS bancolombia;

-- 2. Crear tabla
CREATE TABLE IF NOT EXISTS bancolombia.veredas_proyeccion (
  id                 SERIAL PRIMARY KEY,
  codigo_ver         TEXT NOT NULL,
  nombre_ver         TEXT NOT NULL,
  nomb_mpio          TEXT,
  nom_dep            TEXT DEFAULT 'CAQUETÁ',
  area_ha            NUMERIC(12,2),
  anio_intervencion  INTEGER NOT NULL,
  geojson_feature    JSONB NOT NULL
);

-- 3. Índice por año (para el slider)
CREATE INDEX IF NOT EXISTS idx_veredas_anio ON bancolombia.veredas_proyeccion (anio_intervencion);

-- 4. Habilitar acceso público de lectura (RLS)
ALTER TABLE bancolombia.veredas_proyeccion ENABLE ROW LEVEL SECURITY;
CREATE POLICY "public read" ON bancolombia.veredas_proyeccion FOR SELECT USING (true);

